```tsx
import { useId } from "react";
import "./SettingsToggleRow.css";

export interface SettingsToggleRowProps {
  label: string;
  hint: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

export function SettingsToggleRow({
  label,
  hint,
  checked,
  onChange,
}: SettingsToggleRowProps) {
  const labelId = useId();
  const hintId = useId();

  return (
    <div className="settings-toggle-row">
      <div className="settings-toggle-row__text">
        <span id={labelId} className="settings-toggle-row__label">
          {label}
        </span>
        <span id={hintId} className="settings-toggle-row__hint">
          {hint}
        </span>
      </div>
      <button
        type="button"
        className="settings-toggle-row__switch"
        aria-pressed={checked}
        aria-labelledby={labelId}
        aria-describedby={hintId}
        onClick={() => onChange(!checked)}
      >
        <span className="settings-toggle-row__thumb" aria-hidden="true" />
      </button>
    </div>
  );
}
```

```css
/*
 * Focus: this component relies on the global rule
 *   :focus-visible { outline: 3px solid var(--cresyl); outline-offset: 3px; }
 * and never removes the outline.
 */

.settings-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: clamp(0.75rem, 2vw, 1.5rem);
  padding: clamp(0.75rem, 1.5vw, 1rem) 0;
  border-bottom: 1px solid var(--hair);
  color: var(--ink);
  font: inherit;
}

.settings-toggle-row__text {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
  flex: 1 1 auto;
}

.settings-toggle-row__label {
  font-size: clamp(0.95rem, 1.2vw, 1.1rem);
  color: var(--ink);
}

.settings-toggle-row__hint {
  font-size: clamp(0.8rem, 1vw, 0.9rem);
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.settings-toggle-row__switch {
  position: relative;
  flex: 0 0 auto;
  box-sizing: border-box;
  width: 3rem;
  height: 1.75rem;
  padding: 0;
  margin: 0;
  border: 2px solid var(--muted);
  border-radius: 999px;
  background: var(--slide);
  cursor: pointer;
  font: inherit;
  transition:
    background-color 0.2s ease,
    border-color 0.2s ease;
}

.settings-toggle-row__switch[aria-pressed="true"] {
  background: var(--myelin);
  border-color: var(--myelin);
}

.settings-toggle-row__thumb {
  position: absolute;
  top: 50%;
  left: 0.25rem;
  width: 1.125rem;
  height: 1.125rem;
  border-radius: 999px;
  background: var(--muted);
  transform: translateY(-50%);
  transition:
    transform 0.2s ease,
    background-color 0.2s ease;
}

.settings-toggle-row__switch[aria-pressed="true"] .settings-toggle-row__thumb {
  background: var(--slide);
  transform: translate(1.125rem, -50%);
}

:root[data-motion="reduce"] .settings-toggle-row__switch,
:root[data-motion="reduce"] .settings-toggle-row__thumb {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .settings-toggle-row__switch,
  .settings-toggle-row__thumb {
    transition: none;
  }
}
